@@ -1,104 +0,0 @@
-const express = require('express');
-const swaggerUi = require('swagger-ui-express');
-const YAML = require('yamljs');
-const path = require('path');
-const fs = require('fs');
-const http = require('http');
-const https = require('https');
-const { URL } = require('url');
-
-const app = express();
-const specPath = path.join(__dirname, 'openapi.yaml');
-
-// Keep Swagger "Try it out" same-origin through this proxy path.
-// This avoids browser CORS failures and localhost/IPv6 surprises.
-const proxyMountPath = '/__backend_proxy';
-const backendBaseUrl = new URL(process.env.COOPAIN_API_BASE_URL || 'http://127.0.0.1:8000');
-
-if (!fs.existsSync(specPath)) {
-  console.error(`Fichier introuvable : ${specPath}`);
-  process.exit(1);
-}
-
-const swaggerDocument = YAML.load(specPath);
-
-// IMPORTANT:
-// We intentionally override servers at runtime. Agents/users can replace
-// openapi.yaml safely without breaking Swagger calls, as long as this stays.
-const proxiedSwaggerDocument = JSON.parse(JSON.stringify(swaggerDocument));
-proxiedSwaggerDocument.servers = [
-  {
-    url: proxyMountPath,
-    description: `Local proxy to ${backendBaseUrl.origin}`,
-  },
-];
-
-function buildProxyTargetUrl(req) {
-  const requestPath = req.originalUrl.startsWith(proxyMountPath)
-    ? req.originalUrl.slice(proxyMountPath.length) || '/'
-    : (req.url || '/');
-
-  const basePath = backendBaseUrl.pathname.replace(/\/$/, '');
-  const normalizedPath = requestPath.startsWith('/') ? requestPath : `/${requestPath}`;
-  return new URL(`${backendBaseUrl.origin}${basePath}${normalizedPath}`);
-}
-
-function proxyToBackend(req, res) {
-  const targetUrl = buildProxyTargetUrl(req);
-  const transport = targetUrl.protocol === 'https:' ? https : http;
-
-  const headers = { ...req.headers };
-  headers.host = targetUrl.host;
-
-  const proxyReq = transport.request(
-    {
-      protocol: targetUrl.protocol,
-      hostname: targetUrl.hostname,
-      port: targetUrl.port || undefined,
-      method: req.method,
-      path: `${targetUrl.pathname}${targetUrl.search}`,
-      headers,
-    },
-    (proxyRes) => {
-      res.status(proxyRes.statusCode || 502);
-      for (const [headerName, headerValue] of Object.entries(proxyRes.headers)) {
-        if (headerValue !== undefined) {
-          res.setHeader(headerName, headerValue);
-        }
-      }
-      proxyRes.pipe(res);
-    }
-  );
-
-  proxyReq.on('error', (error) => {
-    if (res.headersSent) {
-      res.end();
-      return;
-    }
-    res.status(502).json({
-      detail: `Proxy request to backend failed: ${error.message}`,
-      backend_base_url: backendBaseUrl.toString(),
-      target_url: targetUrl.toString(),
-    });
-  });
-
-  req.pipe(proxyReq);
-}
-
-app.use('/openapi.yaml', express.static(specPath));
-app.use(proxyMountPath, proxyToBackend);
-app.use(
-  '/api-docs',
-  swaggerUi.serve,
-  swaggerUi.setup(proxiedSwaggerDocument, {
-    swaggerOptions: {
-      validatorUrl: null,
-    },
-  })
-);
-
-const PORT = process.env.PORT || 3000;
-app.listen(PORT, () => {
-  console.log(`Swagger UI disponible sur http://localhost:${PORT}/api-docs`);
-  console.log(`Proxying API calls to ${backendBaseUrl.toString()} via ${proxyMountPath}`);
-});
